BEGIN = "<!-- MBM-MAKER-SPLASH:BEGIN generated by tools/render_maker_splash.py, do not edit by hand -->"
END = "<!-- MBM-MAKER-SPLASH:END -->"
REGION_RE = re.compile(r"(?:\r?\n)?" + re.escape(BEGIN) + r".*?" + re.escape(END) + r"(?:\r?\n)?", re.DOTALL)

LEGACY_REGIONS = (
    re.compile(
        re.escape("<!-- MBM-SPLASH:BEGIN generated by tools/render_splash.py, do not edit by hand -->")
        + r".*?"
        + re.escape("<!-- MBM-SPLASH:END -->")
        + r"\n?",
        re.DOTALL,
    ),
    re.compile(
        re.escape("<!-- MBM-LIVETEACH-SPLASH:BEGIN")
        + r".*?"
        + re.escape("<!-- MBM-LIVETEACH-SPLASH:END -->")
        + r"\n?",
        re.DOTALL,
    ),
    re.compile(r"<!--\s*mbm-splash[^>]*\bSTART\s*-->.*?<!--\s*mbm-splash[^>]*\bEND\s*-->\s*", re.DOTALL | re.IGNORECASE),
)


